require("nvchad.configs.lspconfig").defaults()

-- binaries are provided by home/programs/neovim.nix, not Mason
local servers = {
  "lua_ls",
  "nil_ls",
  "html",
  "cssls",
  "jsonls",
  "ts_ls",
  "pyright",
  "bashls",
  "clangd",
  "qmlls",
}

vim.lsp.config("nil_ls", {
  settings = {
    ["nil"] = {
      formatting = { command = { "nixfmt" } },
    },
  },
})

-- Same flags as .vscode/settings.json in playground/cpp. clangd reads
-- compile_commands.json from the project root (generated by `make`);
-- --query-driver lets it ask the nix-store g++ for system header paths.
vim.lsp.config("clangd", {
  cmd = {
    "clangd",
    "--background-index",
    "--clang-tidy",
    "--header-insertion=never",
    "--completion-style=detailed",
    "--query-driver=/nix/store/*/bin/*",
  },
})

vim.lsp.enable(servers)

-- read :h vim.lsp.config for changing options of lsp servers
